/**
 * The battle viewer's game data: BattleVisuals.json (sprites, prefabs, configs, clips, all
 * extracted from the game's Unity assets by reverseForge/extract_battle_visuals.py) plus the
 * texture sheets it points at. Everything is loaded once and cached.
 */

import assetVersions from '../../../data/assetVersions.json';

/**
 * Texture folder the visuals are read from: the newest one holding a BattleVisuals.json, from
 * src/data/assetVersions.json (regenerated by `npm run update-configs`). A new build's folder is
 * used as soon as extract_battle_visuals.py has written its BattleVisuals.json there.
 */
export const BATTLE_VISUALS_VERSION: string = assetVersions.battleVisuals[assetVersions.battleVisuals.length - 1];

export interface SpriteDef {
    tex: string;
    /** Texture rect, top-left origin, in pixels. */
    x: number; y: number; w: number; h: number;
    /** Pivot, normalised from the bottom-left of the full sprite rect. */
    px: number; py: number;
    ppu: number;
    /** Full sprite rect size and where the packed texture rect sits inside it. */
    ow: number; oh: number; ox: number; oy: number;
}

/**
 * A MinMaxCurve. Curve keys are [time, value] or, from 2026_10_27_09_45, [time, value, inSlope,
 * outSlope] (Hermite); `wrap` is [m_PreInfinity, m_PostInfinity] with 0 PingPong, 1 Repeat, 2 Clamp.
 */
export interface ParticleCurve { min: number; max: number; curve?: number[][]; minCurve?: number[][] | null; wrap?: [number, number] }
export interface ParticleGradient { c: [number, number, number, number][]; a: [number, number][] }
export interface ParticleColor { mode: 'color' | 'twoColors' | 'gradient' | 'twoGradients'; min?: number[]; max?: number[]; g?: ParticleGradient; g2?: ParticleGradient }
export interface ParticleDef {
    duration: number; loop: boolean; prewarm: boolean; delay: ParticleCurve; simSpeed: number;
    lifetime: ParticleCurve; speed: ParticleCurve; size: ParticleCurve; rotation: ParticleCurve;
    color: ParticleColor; gravity: ParticleCurve; maxParticles: number;
    rate: ParticleCurve; bursts: { t: number; n: number; cycles: number; interval: number }[];
    shape: { on: boolean; type: number; radius: number; angle: number; arc: number; scale: [number, number]; pos: [number, number]; rot: [number, number, number] };
    sizeOverLife?: ParticleCurve; colorOverLife?: ParticleColor; rotOverLife?: ParticleCurve;
    /** SizeModule.separateAxes: sizeOverLife is the X size and this the Y size. */
    sizeOverLifeY?: ParticleCurve;
    /** The system's local rotation when it turns about X or Y, which the 2D matrix cannot hold. */
    q?: [number, number, number, number];
    velocity?: { x: ParticleCurve; y: ParticleCurve; space?: number };
    uv?: { sprites: string[] };
    renderer?: { mode: number; order: number; layer: number; material?: { tex: Record<string, string>; colors?: Record<string, number[]> } | null };
}

export interface PrefabNode {
    n: string;
    /** Parent index (-1 = root). */
    p: number;
    path: string;
    /** Local 2D affine [a, b, c, d, tx, ty]. */
    m: number[];
    off?: 1;
    s?: string | null;
    c?: number[];
    o?: number;
    l?: number;
    fx?: 1;
    fy?: 1;
    srOff?: 1;
    sg?: [number, number];
    ps?: ParticleDef;
    anim?: string | null;
    mb?: Record<string, any>;
    mat?: { name: string; shader?: string; floats: Record<string, number>; colors: Record<string, number[]> };
    scripts?: string[];
    isMask?: 1;
}

export interface Prefab { nodes: PrefabNode[] }

export interface ItemVisual {
    prefab: string | null;
    hideBodyPart: boolean;
    /**
     * EquipmentItemVisualConfig.BodyPartsToTurnOff: the character's parts this item hides while
     * shown (BodyPart Head 0, Body 1, Hand 2), e.g. the boxing glove hides the hands.
     */
    turnOff?: number[];
    controller?: string | null;
    dualWield?: boolean;
    hasProjectile?: boolean;
    projectile?: string | null;
    hasSecondary?: boolean;
    secondary?: string | null;
}

export interface MapConfig { ground: number[]; maps: string[] }

export interface ClipCurve { path: string; prop: string; c: string; v: number[] }
export interface Clip { length: number; loop: boolean; rate: number; curves: ClipCurve[]; events: { t: number; fn: string }[] }

export interface FontGlyph { adv: number; bx: number; by: number; w: number; h: number; sx: number; sy: number; sw: number; sh: number }

export interface BattleVisualData {
    version: string;
    sprites: Record<string, SpriteDef>;
    textures: Record<string, { w: number; h: number }>;
    prefabs: Record<string, Prefab>;
    ages: { name: string; color: number[]; ground: number[]; maps: string[]; items: Record<string, (string | null)[]> }[];
    dungeons: Record<string, MapConfig & { title: string; background: string | null }>;
    pvpMaps: Record<'ChatPvpMap' | 'ArenaPvpMap' | 'GuildWarMap', MapConfig>;
    defaultWeapon: string;
    visuals: Record<string, ItemVisual>;
    skins: { name: string; itemType: number; skinVisualId: number; main: string | null; secondary: string | null }[];
    /**
     * BaseSetId -> the set's effect prefabs (SetVisualConfig): `idle` plays around a unit wearing the
     * set complete with every piece at max level, `death` where it dies (UnitSetEffectsView).
     */
    setEffects?: Record<string, { idle: string | null; death: string | null }>;
    skills: Record<string, { showDuration: boolean; icons: string[]; projectiles: string[]; animations: string[] }>;
    skillIds: Record<string, number>;
    pets: Record<string, { name: string; prefabs: string[] }[]>;
    mounts: Record<string, { name: string; prefabs: string[] }[]>;
    clips: Record<string, Clip>;
    controllers: Record<string, { base: string | null; clips: Record<string, string> }>;
    sortingLayers: { name: string; id: number }[];
    font: {
        texture: string; bakeScale: number; pointSize: number; lineHeight: number; ascent: number; descent: number;
        glyphs: Record<string, FontGlyph>;
        label: { rect: [number, number]; anchoredY: number; fontSizeMax: number; fontSizeMin: number; autoSize: boolean; color: number[] };
    } | null;
    constants: {
        cameraOrthoSize: number;
        referenceResolution: [number, number];
        cameraTweenSeconds: number;
        combatCenterOffsetX: number;
        forceCamX: number;
        missionCombatCenterX: number;
        dungeonEnemyColors?: Record<string, { skin: number[]; body: number[] }>;
        /** RarityExtensions.GetColor: skill button RarityBackground tint per Rarity name (RGBA 0..1). */
        rarityColors?: Record<string, number[]>;
        dmgLabel: {
            riseY: number; durationMin: number; durationMax: number; critDurationMulti: number; critSizeMulti: number;
            scaleStart: number; scalePerT: number; rotationDegPerT: number; staticArc: number; staticOffsetY: number;
        };
    };
}

const base = () => `${import.meta.env.BASE_URL}Texture2D/${BATTLE_VISUALS_VERSION}/`;

let dataPromise: Promise<BattleVisualData> | null = null;

export function loadBattleVisuals(): Promise<BattleVisualData> {
    if (!dataPromise) {
        dataPromise = fetch(`${base()}BattleVisuals.json`).then(r => {
            const type = r.headers.get('content-type') || '';
            if (!r.ok || type.includes('text/html')) throw new Error(`BattleVisuals.json: ${r.status}`);
            return r.json();
        });
        dataPromise.catch(() => { dataPromise = null; });
    }
    return dataPromise;
}

/** Texture sheets, loaded on first use. `get` returns null until the image is ready. */
export class TextureCache {
    private images = new Map<string, HTMLImageElement | null>();
    private failed = new Set<string>();
    onLoad: (() => void) | null = null;

    get(name: string): HTMLImageElement | null {
        const hit = this.images.get(name);
        if (hit !== undefined) return hit && hit.complete && hit.naturalWidth > 0 ? hit : null;
        if (this.failed.has(name)) return null;
        const img = new Image();
        img.decoding = 'async';
        this.images.set(name, img);
        img.onload = () => this.onLoad?.();
        img.onerror = () => { this.images.set(name, null); this.failed.add(name); };
        img.src = `${base()}${encodeURIComponent(name)}.png`;
        return null;
    }
}
